cat > ApiMcpServer/ApiTools.cs << 'EOF'
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

[McpServerToolType]
public class ApiTools(IHttpClientFactory httpClientFactory, ILogger<ApiTools> logger)
{
    private HttpClient CreateClient() => httpClientFactory.CreateClient("Api");

    [McpServerTool, Description("List all posts from the API. Returns titles and IDs.")]
    public async Task<string> ListPosts(CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Listing posts");
        var client = CreateClient();
        var posts = await client.GetFromJsonAsync<JsonElement[]>("/posts", cancellationToken);
        var summary = posts!
            .Take(10)
            .Select(p => $"[{p.GetProperty("id")}] {p.GetProperty("title").GetString()}");
        return string.Join("\n", summary);
    }

    [McpServerTool, Description("Get a single post by its numeric ID.")]
    public async Task<string> GetPost(
        [Description("The numeric ID of the post to retrieve")] int postId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Getting post {PostId}", postId);
        var client = CreateClient();
        var post = await client.GetFromJsonAsync<JsonElement>($"/posts/{postId}", cancellationToken);
        return JsonSerializer.Serialize(post, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerTool, Description("Search posts by keyword in the title. Returns matching posts.")]
    public async Task<string> SearchPosts(
        [Description("Keyword to search for in post titles")] string keyword,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Searching posts for '{Keyword}'", keyword);
        var client = CreateClient();
        var posts = await client.GetFromJsonAsync<JsonElement[]>("/posts", cancellationToken);
        var matches = posts!
            .Where(p => p.GetProperty("title").GetString()!
                .Contains(keyword, StringComparison.OrdinalIgnoreCase))
            .Select(p => $"[{p.GetProperty("id")}] {p.GetProperty("title").GetString()}");
        var result = matches.ToList();
        return result.Count > 0
            ? string.Join("\n", result)
            : "No posts found matching that keyword.";
    }
}
EOF
